// Emits sdk/idl.json (runtime IDL, snake_case as Anchor expects) and
// sdk/kestrel.ts (camelCase TS type, same as `anchor build` writes to target/types).
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { createRequire } from "node:module";
const require = createRequire(import.meta.url);
const { convertIdlToCamelCase } = require("@coral-xyz/anchor/dist/cjs/idl.js");

const idl = JSON.parse(readFileSync(new URL("../target/idl/kestrel.json", import.meta.url), "utf8"));
const camel = convertIdlToCamelCase(idl);
const typeFile =
  "// AUTO-GENERATED by scripts/gen-types.mjs from target/idl/kestrel.json\n" +
  `export type Kestrel = ${JSON.stringify(camel, null, 2)};\n`;
for (const dir of ["../sdk", "../app/src/generated"]) {
  try {
    mkdirSync(new URL(dir + "/", import.meta.url), { recursive: true });
    writeFileSync(new URL(`${dir}/idl.json`, import.meta.url), JSON.stringify(idl, null, 2));
    writeFileSync(new URL(`${dir}/kestrel.ts`, import.meta.url), typeFile);
  } catch {}
}
console.log("wrote sdk/idl.json + sdk/kestrel.ts");
